package crash

import (
	"bytes"
	"encoding/json"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"
)

func TestMiddlewareReportsPanics(t *testing.T) {
	var out bytes.Buffer
	ring := NewLogRing(slog.DiscardHandler, 5, time.Now)
	log := slog.New(ring)
	rep := NewReporter(&out, time.Now)
	rep.Logs = ring
	h := rep.Middleware(http.HandlerFunc(func(_ http.ResponseWriter, r *http.Request) {
		var body struct{ Name string }
		if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
			t.Error(err)
		}
		log.Info("handling", "name", body.Name)
		panic("boom: " + body.Name)
	}))
	req := httptest.NewRequestWithContext(t.Context(), http.MethodPost, "/things?x=1", strings.NewReader(`{"Name":"ana"}`))
	req.Header.Set("User-Agent", "test")
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	if rec.Code != http.StatusInternalServerError {
		t.Errorf("status = %d, want 500", rec.Code)
	}
	var r Report
	if err := json.Unmarshal(out.Bytes(), &r); err != nil {
		t.Fatal(err)
	}
	if r.Kind != "panic" || r.Panic != "boom: ana" {
		t.Errorf("report kind %q panic %q", r.Kind, r.Panic)
	}
	if r.Request.Body != `{"Name":"ana"}` || r.Request.Query != "x=1" || r.Request.Headers["User-Agent"] != "test" {
		t.Errorf("request = %+v", r.Request)
	}
	if !strings.Contains(r.Stack, "TestMiddlewareReportsPanics") {
		t.Errorf("stack doesn't show the handler:\n%s", r.Stack)
	}
	if len(r.Logs) != 1 || !strings.Contains(r.Logs[0], "name=ana") {
		t.Errorf("logs = %q", r.Logs)
	}
}

func TestCheckReportsStuckRequests(t *testing.T) {
	var out bytes.Buffer
	now := time.Date(2026, 9, 7, 8, 0, 0, 0, time.UTC)
	rep := NewReporter(&out, func() time.Time { return now })
	release := make(chan struct{})
	started := make(chan struct{})
	h := rep.Middleware(http.HandlerFunc(func(http.ResponseWriter, *http.Request) {
		close(started)
		<-release
	}))
	done := make(chan struct{})
	go func() {
		h.ServeHTTP(httptest.NewRecorder(), httptest.NewRequestWithContext(t.Context(), http.MethodGet, "/slow", nil))
		close(done)
	}()
	<-started
	if rep.Check(time.Minute) {
		t.Error("reported a request that isn't stuck yet")
	}
	now = now.Add(2 * time.Minute)
	if !rep.Check(time.Minute) {
		t.Error("didn't report a stuck request")
	}
	if rep.Check(time.Minute) {
		t.Error("reported the same request twice")
	}
	close(release)
	<-done
	var r Report
	if err := json.Unmarshal(out.Bytes(), &r); err != nil {
		t.Fatal(err)
	}
	if r.Kind != "stuck" || r.Request.Path != "/slow" || !strings.Contains(r.Stack, "goroutine") {
		t.Errorf("report = %+v", r)
	}
}

func TestLogRingKeepsLastLines(t *testing.T) {
	ring := NewLogRing(slog.DiscardHandler, 2, time.Now)
	log := slog.New(ring).With("svc", "remind")
	for _, m := range []string{"one", "two", "three"} {
		log.Info(m, "n", 1)
	}
	got := ring.Lines()
	if len(got) != 2 || !strings.Contains(got[0], "INFO two svc=remind n=1") {
		t.Errorf("Lines = %q", got)
	}
}

// Package api serves remind's HTTP API.
package api

import (
	"encoding/json"
	"errors"
	"io"
	"log/slog"
	"net/http"
	"strconv"
	"time"

	"example.com/remind/audit"
	"example.com/remind/auth"
	"example.com/remind/notify"
	"example.com/remind/quota"
	"example.com/remind/search"
	"example.com/remind/share"
	"example.com/remind/store"
)

// API holds what the handlers need.
type API struct {
	Store    *store.Store
	Notify   *notify.Dispatcher
	Lists    *share.Lists
	Search   *search.Index
	Audit    *audit.Log
	Limiter  *quota.Limiter // per-user rate limits; nil turns them off
	Metrics  http.Handler   // served at /metrics if not nil
	Log      *slog.Logger
	Now      func() time.Time
	Snapshot func() (io.WriteCloser, error) // where admin snapshots go
}

// planOf returns the user's plan, defaulting to the free plan.
func planOf(u *store.User) quota.Plan {
	p, err := quota.PlanByName(u.Plan)
	if err != nil {
		return quota.Free
	}
	return p
}

// limit applies the per-user rate limit, if there is one.
func (a *API) limit(h http.Handler) http.Handler {
	if a.Limiter == nil {
		return h
	}
	return quota.Middleware(a.Limiter, func(r *http.Request) (string, quota.Plan) {
		u := auth.UserFrom(r.Context())
		return u.ID, planOf(u)
	}, h)
}

// Routes returns the API's handler.
func (a *API) Routes() http.Handler {
	mux := http.NewServeMux()
	user := func(h http.HandlerFunc) http.Handler { return auth.Require(a.Store, a.limit(h)) }
	admin := func(h http.HandlerFunc) http.Handler { return auth.RequireAdmin(a.Store, h) }

	mux.Handle("POST /v1/reminders", user(a.createReminder))
	mux.Handle("GET /v1/reminders", user(a.listReminders))
	mux.Handle("GET /v1/reminders/{id}", user(a.getReminder))
	mux.Handle("DELETE /v1/reminders/{id}", user(a.deleteReminder))
	mux.Handle("POST /v1/reminders/{id}/done", user(a.markDone))
	mux.Handle("POST /v1/reminders/{id}/snooze", user(a.snooze))
	mux.Handle("POST /v1/reminders/{id}/test", user(a.testNotify))

	mux.Handle("GET /v1/me", user(a.me))
	mux.Handle("DELETE /v1/me", user(a.closeAccount))
	mux.Handle("PUT /v1/me/prefs", user(a.updatePrefs))
	mux.Handle("GET /v1/me/digest", user(a.digest))
	mux.Handle("GET /v1/me/calendar.ics", user(a.calendarFeed))
	mux.Handle("GET /v1/search", user(a.search))

	mux.Handle("POST /v1/lists", user(a.createList))
	mux.Handle("GET /v1/lists", user(a.listLists))
	mux.Handle("GET /v1/lists/{id}", user(a.getList))
	mux.Handle("DELETE /v1/lists/{id}", user(a.deleteList))
	mux.Handle("POST /v1/lists/{id}/members", user(a.addMember))
	mux.Handle("DELETE /v1/lists/{id}/members/{user}", user(a.removeMember))
	mux.Handle("POST /v1/lists/{id}/reminders", user(a.addListReminder))
	mux.Handle("DELETE /v1/lists/{id}/reminders/{reminder}", user(a.removeListReminder))

	// Read-only views of the caller's own data.
	mux.HandleFunc("GET /v1/me/export", a.export)
	mux.HandleFunc("GET /v1/me/stats", a.stats)

	mux.Handle("POST /v1/admin/users/import", admin(a.importUsers))
	mux.Handle("DELETE /v1/admin/users/{id}", admin(a.deleteUser))
	mux.Handle("POST /v1/admin/dispatcher/stop", admin(a.stopDispatcher))
	mux.Handle("POST /v1/admin/snapshot", admin(a.snapshot))
	mux.Handle("GET /v1/admin/dispatcher/status", admin(a.dispatcherStatus))
	mux.Handle("GET /v1/admin/audit", admin(a.auditLog))

	if a.Metrics != nil {
		mux.Handle("GET /metrics", a.Metrics)
	}

	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		a.writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})
	return mux
}

// decode reads a JSON request body into v, answering 400 on failure.
func (a *API) decode(w http.ResponseWriter, r *http.Request, v any) bool {
	if err := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20)).Decode(v); err != nil {
		a.fail(w, http.StatusBadRequest, "bad JSON: "+err.Error())
		return false
	}
	return true
}

func (a *API) writeJSON(w http.ResponseWriter, status int, v any) {
	b, err := json.Marshal(v)
	if err != nil {
		a.Log.Error("encode response", "err", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if _, err := w.Write(append(b, '\n')); err != nil {
		a.Log.Debug("write response", "err", err)
	}
}

func (a *API) fail(w http.ResponseWriter, status int, msg string) {
	a.writeJSON(w, status, map[string]string{"error": msg})
}

// writeError answers with the status that matches a store error.
func (a *API) writeError(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, store.ErrNotFound):
		a.fail(w, http.StatusNotFound, "not found")
	case errors.Is(err, store.ErrConflict):
		a.fail(w, http.StatusConflict, "conflict")
	default:
		a.Log.Error("request failed", "err", err)
		a.fail(w, http.StatusInternalServerError, "internal error")
	}
}

// page reads offset and limit from the query.
func (a *API) page(w http.ResponseWriter, r *http.Request) (offset, limit int, ok bool) {
	offset, limit = 0, 50
	q := r.URL.Query()
	var err error
	if s := q.Get("offset"); s != "" {
		if offset, err = strconv.Atoi(s); err != nil || offset < 0 {
			a.fail(w, http.StatusBadRequest, "offset must be a whole number")
			return 0, 0, false
		}
	}
	if s := q.Get("limit"); s != "" {
		if limit, err = strconv.Atoi(s); err != nil || limit < 1 || limit > 100 {
			a.fail(w, http.StatusBadRequest, "limit must be between 1 and 100")
			return 0, 0, false
		}
	}
	return offset, limit, true
}

package store

import (
	"bytes"
	"errors"
	"strings"
	"testing"
	"time"

	"example.com/remind/schedule"
)

var t0 = time.Date(2026, 9, 7, 8, 0, 0, 0, time.UTC)

func newStore() *Store {
	return New(func() time.Time { return t0 })
}

func TestCreateGet(t *testing.T) {
	s := newStore()
	r := s.Create("u1", "water the plants", t0.Add(time.Hour), nil)
	got, err := s.Get(r.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.Text != "water the plants" || !got.Due.Equal(t0.Add(time.Hour)) {
		t.Errorf("Get = %+v", got)
	}
	if _, err := s.Get("rem_9999"); !errors.Is(err, ErrNotFound) {
		t.Errorf("Get(missing) error = %v, want ErrNotFound", err)
	}
}

func TestCreateRecurring(t *testing.T) {
	s := newStore()
	rule, err := schedule.Parse("every 2h", nil, t0)
	if err != nil {
		t.Fatal(err)
	}
	r := s.Create("u1", "stretch", time.Time{}, rule)
	if want := t0.Add(2 * time.Hour); !r.Due.Equal(want) {
		t.Errorf("Due = %v, want %v", r.Due, want)
	}
	s.MarkSent(r.ID)
	if want := t0.Add(4 * time.Hour); !r.Due.Equal(want) {
		t.Errorf("after MarkSent, Due = %v, want %v", r.Due, want)
	}
}

func TestList(t *testing.T) {
	s := newStore()
	for _, text := range []string{"a", "b", "c"} {
		s.Create("u1", text, t0, nil)
	}
	if got := s.List("u1", 0, 2); len(got) != 2 || got[0].Text != "a" {
		t.Errorf("List(0, 2) = %v", got)
	}
	if got := s.List("u1", 2, 50); len(got) != 1 || got[0].Text != "c" {
		t.Errorf("List(2, 50) = %v", got)
	}
}

func TestDelete(t *testing.T) {
	s := newStore()
	r := s.Create("u1", "a", t0, nil)
	if err := s.Delete(r.ID); err != nil {
		t.Fatal(err)
	}
	if got := s.List("u1", 0, 50); len(got) != 0 {
		t.Errorf("List after Delete = %v", got)
	}
	if err := s.Delete(r.ID); !errors.Is(err, ErrNotFound) {
		t.Errorf("second Delete error = %v, want ErrNotFound", err)
	}
	if err := s.Update(r.ID, func(*Reminder) error { return nil }); !errors.Is(err, ErrNotFound) {
		t.Errorf("Update after Delete error = %v, want ErrNotFound", err)
	}
}

func TestDue(t *testing.T) {
	s := newStore()
	early := s.Create("u1", "early", t0.Add(-time.Hour), nil)
	s.Create("u1", "later", t0.Add(time.Hour), nil)
	got := s.Due(t0)
	if len(got) != 1 || got[0] != early {
		t.Errorf("Due = %v, want [early]", got)
	}
	s.MarkSent(early.ID)
	if got := s.Due(t0); len(got) != 0 {
		t.Errorf("Due after MarkSent = %v, want none", got)
	}
}

func TestUpcoming(t *testing.T) {
	s := newStore()
	rule, err := schedule.Parse("every 1d", nil, t0)
	if err != nil {
		t.Fatal(err)
	}
	s.Create("u1", "daily", time.Time{}, rule)
	s.Create("u1", "once", t0.Add(30*time.Hour), nil)
	got := s.Upcoming("u1", t0, t0.Add(3*24*time.Hour))
	var texts []string
	for _, o := range got {
		texts = append(texts, o.Text)
	}
	if want := "daily once daily"; strings.Join(texts, " ") != want {
		t.Errorf("Upcoming = %v, want %s", texts, want)
	}
}

func TestOnChange(t *testing.T) {
	s := newStore()
	var seen []string
	s.OnChange(func(r *Reminder) { seen = append(seen, r.ID) })
	r := s.Create("u1", "a", t0, nil)
	if err := s.Update(r.ID, func(r *Reminder) error { r.Done = true; return nil }); err != nil {
		t.Fatal(err)
	}
	if len(seen) != 2 {
		t.Errorf("OnChange calls = %v, want 2", seen)
	}
}

func TestUsers(t *testing.T) {
	s := newStore()
	if err := s.AddUser(User{ID: "u1", Name: "Ana", Token: "tok1"}); err != nil {
		t.Fatal(err)
	}
	u, err := s.UserByToken("tok1")
	if err != nil {
		t.Fatal(err)
	}
	if u.Prefs == nil || u.Prefs.Channel != "email" {
		t.Errorf("new user prefs = %+v, want the defaults", u.Prefs)
	}
	if err := s.AddUser(User{ID: "u1"}); !errors.Is(err, ErrConflict) {
		t.Errorf("duplicate AddUser error = %v, want ErrConflict", err)
	}
	n := s.ImportUsers([]User{{ID: "u1"}, {ID: "u2", Name: "Bo", Token: "tok2", Prefs: &Prefs{Channel: "email"}}})
	if n != 1 {
		t.Errorf("ImportUsers added %d, want 1", n)
	}
	if err := s.DeleteUser("u2"); err != nil {
		t.Fatal(err)
	}
	if _, err := s.UserByToken("tok2"); !errors.Is(err, ErrNotFound) {
		t.Errorf("token after DeleteUser error = %v, want ErrNotFound", err)
	}
}

func TestSnapshot(t *testing.T) {
	s := newStore()
	if err := s.AddUser(User{ID: "u1", Name: "Ana", Token: "secret"}); err != nil {
		t.Fatal(err)
	}
	s.Create("u1", "a", t0, nil)
	var buf bytes.Buffer
	if err := s.Snapshot(&buf); err != nil {
		t.Fatal(err)
	}
	if strings.Contains(buf.String(), "secret") {
		t.Error("snapshot contains a token")
	}
	if !strings.Contains(buf.String(), "rem_0001") {
		t.Errorf("snapshot = %s, want the reminder", buf.String())
	}
}

// Package share lets users share lists of reminders with each other.
package share

import (
	"cmp"
	"errors"
	"fmt"
	"maps"
	"slices"
	"strings"
	"sync"
	"time"
	"unicode/utf8"
)

// Errors callers check for.
var (
	ErrNotFound  = errors.New("share: not found")
	ErrForbidden = errors.New("share: forbidden")
	ErrInvalid   = errors.New("share: invalid")
)

// maxName is the longest list name, in characters.
const maxName = 80

// A Role is what a member may do with a list. Each role may do
// everything the roles below it may.
type Role int

// The roles, from least to most access.
const (
	Viewer Role = iota + 1 // sees the list and its reminders
	Editor                 // also adds reminders and viewers
	Owner                  // also manages members, renames, and deletes
)

// String returns the role's name: "viewer", "editor", or "owner".
func (r Role) String() string {
	switch r {
	case Viewer:
		return "viewer"
	case Editor:
		return "editor"
	case Owner:
		return "owner"
	}
	return fmt.Sprintf("Role(%d)", int(r))
}

// ParseRole returns the role with the given name.
func ParseRole(s string) (Role, error) {
	switch s {
	case "viewer":
		return Viewer, nil
	case "editor":
		return Editor, nil
	case "owner":
		return Owner, nil
	}
	return 0, fmt.Errorf("parse role %q: %w", s, ErrInvalid)
}

// A List is a named set of reminders shared between its members.
type List struct {
	ID        string
	Name      string
	Owner     string          // user ID of the owner, who is also in Members
	Members   map[string]Role // by user ID
	Reminders []string        // reminder IDs, in the order they were added
	Created   time.Time
}

func (l *List) clone() List {
	c := *l
	c.Members = maps.Clone(l.Members)
	c.Reminders = slices.Clone(l.Reminders)
	return c
}

// Lists holds every shared list. Users who are not members of a list
// get ErrNotFound for it; members whose role does not allow an action
// get ErrForbidden. Lists is safe for concurrent use.
type Lists struct {
	now func() time.Time

	mu    sync.RWMutex
	lists map[string]*List
	seq   int
}

// New returns an empty set of lists. now is its clock.
func New(now func() time.Time) *Lists {
	return &Lists{now: now, lists: make(map[string]*List)}
}

// checkName trims space around a list name and checks its length.
func checkName(name string) (string, error) {
	name = strings.TrimSpace(name)
	if n := utf8.RuneCountInString(name); n < 1 || n > maxName {
		return "", fmt.Errorf("name must be 1 to %d characters: %w", maxName, ErrInvalid)
	}
	return name, nil
}

// member returns the list with the given ID and user's role in it.
func (s *Lists) member(id, user string) (*List, Role, error) {
	l, ok := s.lists[id]
	if !ok {
		return nil, 0, ErrNotFound
	}
	role, ok := l.Members[user]
	if !ok {
		return nil, 0, ErrNotFound
	}
	return l, role, nil
}

// require returns the list with the given ID if by's role in it is at
// least need.
func (s *Lists) require(id, by string, need Role) (*List, error) {
	l, role, err := s.member(id, by)
	if err != nil {
		return nil, err
	}
	if role < need {
		return nil, ErrForbidden
	}
	return l, nil
}

// Create makes a new list owned by owner.
func (s *Lists) Create(owner, name string) (List, error) {
	if owner == "" {
		return List{}, fmt.Errorf("create list: no owner: %w", ErrInvalid)
	}
	name, err := checkName(name)
	if err != nil {
		return List{}, fmt.Errorf("create list: %w", err)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	s.seq++
	l := &List{
		ID:      fmt.Sprintf("lst_%04d", s.seq),
		Name:    name,
		Owner:   owner,
		Members: map[string]Role{owner: Owner},
		Created: s.now(),
	}
	s.lists[l.ID] = l
	return l.clone(), nil
}

// Get returns a list for one of its members.
func (s *Lists) Get(id, user string) (List, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	l, _, err := s.member(id, user)
	if err != nil {
		return List{}, fmt.Errorf("get list %s: %w", id, err)
	}
	return l.clone(), nil
}

// ForUser returns the lists user is a member of, sorted by name.
func (s *Lists) ForUser(user string) []List {
	s.mu.RLock()
	defer s.mu.RUnlock()
	var out []List
	for _, l := range s.lists {
		if _, ok := l.Members[user]; ok {
			out = append(out, l.clone())
		}
	}
	slices.SortFunc(out, func(a, b List) int {
		return cmp.Or(cmp.Compare(a.Name, b.Name), cmp.Compare(a.ID, b.ID))
	})
	return out
}

// AddMember adds user to a list with the given role, or changes the role
// of an existing member. Owners may add anyone; editors may add new
// viewers. A list has one owner: use TransferOwnership to change it.
func (s *Lists) AddMember(id, by, user string, role Role) error {
	switch {
	case user == "":
		return fmt.Errorf("add member to %s: no user: %w", id, ErrInvalid)
	case role == Owner:
		return fmt.Errorf("add member to %s: a list has one owner: %w", id, ErrInvalid)
	case role != Viewer && role != Editor:
		return fmt.Errorf("add member to %s: %v: %w", id, role, ErrInvalid)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	l, byRole, err := s.member(id, by)
	if err != nil {
		return fmt.Errorf("add member to %s: %w", id, err)
	}
	_, exists := l.Members[user]
	switch {
	case byRole == Owner:
	case byRole == Editor && role == Viewer && !exists:
	default:
		return fmt.Errorf("add %s to %s as %v: %w", user, id, role, ErrForbidden)
	}
	if user == l.Owner {
		return fmt.Errorf("add %s to %s: already the owner: %w", user, id, ErrInvalid)
	}
	l.Members[user] = role
	return nil
}

// RemoveMember removes user from a list. Owners may remove anyone but
// themselves, and other members may remove themselves.
func (s *Lists) RemoveMember(id, by, user string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	l, byRole, err := s.member(id, by)
	if err != nil {
		return fmt.Errorf("remove member from %s: %w", id, err)
	}
	switch {
	case user == l.Owner:
		return fmt.Errorf("remove owner from %s: %w", id, ErrForbidden)
	case user != by && byRole != Owner:
		return fmt.Errorf("remove %s from %s: %w", user, id, ErrForbidden)
	}
	if _, ok := l.Members[user]; !ok {
		return fmt.Errorf("remove %s from %s: %w", user, id, ErrNotFound)
	}
	delete(l.Members, user)
	return nil
}

// AddReminder adds a reminder to a list. Adding a reminder already on
// the list does nothing. Editors and owners may add reminders.
func (s *Lists) AddReminder(id, by, reminderID string) error {
	if reminderID == "" {
		return fmt.Errorf("add reminder to %s: no reminder: %w", id, ErrInvalid)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	l, err := s.require(id, by, Editor)
	if err != nil {
		return fmt.Errorf("add reminder to %s: %w", id, err)
	}
	if !slices.Contains(l.Reminders, reminderID) {
		l.Reminders = append(l.Reminders, reminderID)
	}
	return nil
}

// RemoveReminder takes a reminder off a list. Editors and owners may
// remove reminders.
func (s *Lists) RemoveReminder(id, by, reminderID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	l, err := s.require(id, by, Editor)
	if err != nil {
		return fmt.Errorf("remove reminder from %s: %w", id, err)
	}
	i := slices.Index(l.Reminders, reminderID)
	if i < 0 {
		return fmt.Errorf("remove reminder %s from %s: %w", reminderID, id, ErrNotFound)
	}
	l.Reminders = slices.Delete(l.Reminders, i, i+1)
	return nil
}

// Rename changes a list's name. Only the owner may rename a list.
func (s *Lists) Rename(id, by, name string) error {
	name, err := checkName(name)
	if err != nil {
		return fmt.Errorf("rename %s: %w", id, err)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	l, err := s.require(id, by, Owner)
	if err != nil {
		return fmt.Errorf("rename %s: %w", id, err)
	}
	l.Name = name
	return nil
}

// Delete removes a list. Only the owner may delete a list.
func (s *Lists) Delete(id, by string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, err := s.require(id, by, Owner); err != nil {
		return fmt.Errorf("delete list %s: %w", id, err)
	}
	delete(s.lists, id)
	return nil
}

// RemoveUser deletes the lists user owns and takes user off every other
// list, for when an account is closed. It returns how many lists were
// deleted.
func (s *Lists) RemoveUser(user string) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	n := 0
	for id, l := range s.lists {
		if l.Owner == user {
			delete(s.lists, id)
			n++
			continue
		}
		delete(l.Members, user)
	}
	return n
}

// TransferOwnership makes a member the owner of a list, and the old
// owner an editor. Only the owner may transfer a list.
func (s *Lists) TransferOwnership(id, by, to string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	l, err := s.require(id, by, Owner)
	if err != nil {
		return fmt.Errorf("transfer %s: %w", id, err)
	}
	if to == by {
		return fmt.Errorf("transfer %s to %s: already the owner: %w", id, to, ErrInvalid)
	}
	if _, ok := l.Members[to]; !ok {
		return fmt.Errorf("transfer %s to %s: not a member: %w", id, to, ErrInvalid)
	}
	l.Members[by] = Editor
	l.Members[to] = Owner
	l.Owner = to
	return nil
}

package api

import (
	"errors"
	"net/http"

	"example.com/remind/auth"
	"example.com/remind/share"
)

// listError answers with the status that matches a share error.
func (a *API) listError(w http.ResponseWriter, err error) {
	switch {
	case errors.Is(err, share.ErrNotFound):
		a.fail(w, http.StatusNotFound, "not found")
	case errors.Is(err, share.ErrForbidden):
		a.fail(w, http.StatusForbidden, "forbidden")
	case errors.Is(err, share.ErrInvalid):
		a.fail(w, http.StatusBadRequest, err.Error())
	default:
		a.writeError(w, err)
	}
}

func (a *API) createList(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	var req struct {
		Name string `json:"name"`
	}
	if !a.decode(w, r, &req) {
		return
	}
	l, err := a.Lists.Create(u.ID, req.Name)
	if err != nil {
		a.listError(w, err)
		return
	}
	a.writeJSON(w, http.StatusCreated, l)
}

func (a *API) listLists(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	a.writeJSON(w, http.StatusOK, map[string]any{"lists": a.Lists.ForUser(u.ID)})
}

// getList returns a list with the reminders on it.
func (a *API) getList(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	l, err := a.Lists.Get(r.PathValue("id"), u.ID)
	if err != nil {
		a.listError(w, err)
		return
	}
	views := make([]reminderView, 0, len(l.Reminders))
	for _, id := range l.Reminders {
		rem, err := a.Store.Get(id)
		if err != nil {
			continue
		}
		views = append(views, viewOf(rem))
	}
	owner, _ := a.Store.User(l.Owner)
	a.writeJSON(w, http.StatusOK, map[string]any{"list": l, "owner": owner.Name, "reminders": views})
}

func (a *API) addMember(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	var req struct {
		User string `json:"user"`
		Role string `json:"role"`
	}
	if !a.decode(w, r, &req) {
		return
	}
	role, err := share.ParseRole(req.Role)
	if err != nil {
		a.fail(w, http.StatusBadRequest, err.Error())
		return
	}
	if _, err := a.Store.User(req.User); err != nil {
		a.fail(w, http.StatusBadRequest, "no such user")
		return
	}
	id := r.PathValue("id")
	if err := a.Lists.AddMember(id, u.ID, req.User, role); err != nil {
		a.listError(w, err)
		return
	}
	a.Audit.Record(u.ID, "list.member.add", id, req.User+" as "+role.String())
	w.WriteHeader(http.StatusNoContent)
}

func (a *API) removeMember(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	id, member := r.PathValue("id"), r.PathValue("user")
	if err := a.Lists.RemoveMember(id, u.ID, member); err != nil {
		a.listError(w, err)
		return
	}
	a.Audit.Record(u.ID, "list.member.remove", id, member)
	w.WriteHeader(http.StatusNoContent)
}

// addListReminder puts one of the caller's reminders on a list.
func (a *API) addListReminder(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	var req struct {
		Reminder string `json:"reminder"`
	}
	if !a.decode(w, r, &req) {
		return
	}
	rem, err := a.Store.Get(req.Reminder)
	if err != nil {
		a.writeError(w, err)
		return
	}
	if rem.UserID != u.ID {
		a.fail(w, http.StatusNotFound, "not found")
		return
	}
	if err := a.Lists.AddReminder(r.PathValue("id"), u.ID, rem.ID); err != nil {
		a.listError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (a *API) removeListReminder(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	if err := a.Lists.RemoveReminder(r.PathValue("id"), u.ID, r.PathValue("reminder")); err != nil {
		a.listError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (a *API) deleteList(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	id := r.PathValue("id")
	if err := a.Lists.Delete(id, u.ID); err != nil {
		a.listError(w, err)
		return
	}
	a.Audit.Record(u.ID, "list.delete", id, "")
	w.WriteHeader(http.StatusNoContent)
}

// Package calendar writes reminders as iCalendar (RFC 5545) files that
// calendar apps can import or subscribe to.
package calendar

import (
	"fmt"
	"io"
	"strings"
	"time"
	"unicode/utf8"
)

// maxLine is the longest content line, in octets, before it is folded.
const maxLine = 75

// utcFormat is the iCalendar form of a UTC date-time.
const utcFormat = "20060102T150405Z"

// An Event is one calendar entry.
type Event struct {
	UID         string
	Summary     string
	Description string
	Start       time.Time
	Duration    time.Duration
	RRule       string // a recurrence rule such as "FREQ=DAILY", or empty
}

// A Writer writes calendars. The zero value stamps events with the
// current time.
type Writer struct {
	Now func() time.Time // the DTSTAMP clock; nil means time.Now
}

// Write writes events as a calendar, using the current time as each
// event's DTSTAMP.
func Write(w io.Writer, prodID string, events []Event) error {
	return Writer{}.Write(w, prodID, events)
}

// Write writes events to w as a VCALENDAR identified by prodID.
// Every event needs a UID and a start time.
func (cw Writer) Write(w io.Writer, prodID string, events []Event) error {
	now := time.Now
	if cw.Now != nil {
		now = cw.Now
	}
	stamp := now().UTC().Format(utcFormat)

	var b strings.Builder
	line(&b, "BEGIN:VCALENDAR")
	line(&b, "VERSION:2.0")
	line(&b, "PRODID:"+escape(prodID))
	line(&b, "CALSCALE:GREGORIAN")
	for i, e := range events {
		if e.UID == "" {
			return fmt.Errorf("calendar: event %d has no UID", i)
		}
		if e.Start.IsZero() {
			return fmt.Errorf("calendar: event %s has no start time", e.UID)
		}
		line(&b, "BEGIN:VEVENT")
		line(&b, "UID:"+escape(e.UID))
		line(&b, "DTSTAMP:"+stamp)
		line(&b, "DTSTART:"+e.Start.UTC().Format(utcFormat))
		line(&b, "DURATION:"+formatDuration(e.Duration))
		if e.RRule != "" {
			line(&b, "RRULE:"+e.RRule)
		}
		line(&b, "SUMMARY:"+escape(e.Summary))
		if e.Description != "" {
			line(&b, "DESCRIPTION:"+escape(e.Description))
		}
		line(&b, "END:VEVENT")
	}
	line(&b, "END:VCALENDAR")

	if _, err := io.WriteString(w, b.String()); err != nil {
		return fmt.Errorf("write calendar: %w", err)
	}
	return nil
}

// line writes one content line, folding it into lines of at most
// maxLine octets. Continuation lines start with a space.
func line(b *strings.Builder, s string) {
	limit := maxLine
	for len(s) > limit {
		cut := limit
		for !utf8.RuneStart(s[cut]) {
			cut--
		}
		b.WriteString(s[:cut])
		b.WriteString("\r\n ")
		s = s[cut:]
		limit = maxLine - 1
	}
	b.WriteString(s)
	b.WriteString("\r\n")
}

var textEscaper = strings.NewReplacer(
	`\`, `\\`,
	";", `\;`,
	",", `\,`,
	"\r\n", `\n`,
	"\n", `\n`,
	"\r", `\n`,
)

// escape escapes a TEXT property value.
func escape(s string) string {
	return textEscaper.Replace(s)
}

// formatDuration formats d as an iCalendar duration such as "PT15M" or
// "P1DT2H". Fractions of a second are dropped.
func formatDuration(d time.Duration) string {
	var b strings.Builder
	if d < 0 {
		b.WriteByte('-')
		d = -d
	}
	b.WriteByte('P')
	secs := int64(d / time.Second)
	days := secs / 86400
	parts := [3]int64{secs % 86400 / 3600, secs % 3600 / 60, secs % 60}
	if days > 0 {
		fmt.Fprintf(&b, "%dD", days)
	}

	// RFC 5545 doesn't allow gaps (hours then seconds without minutes),
	// so write every unit from the first nonzero one to the last.
	first, last := -1, -1
	for i, p := range parts {
		if p != 0 {
			if first < 0 {
				first = i
			}
			last = i
		}
	}
	if first < 0 {
		if days == 0 {
			b.WriteString("T0S")
		}
		return b.String()
	}
	b.WriteByte('T')
	for i := first; i <= last; i++ {
		fmt.Fprintf(&b, "%d%c", parts[i], "HMS"[i])
	}
	return b.String()
}

// Package server assembles remind from its parts.
package server

import (
	"context"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"time"

	"example.com/remind/api"
	"example.com/remind/audit"
	"example.com/remind/crash"
	"example.com/remind/metrics"
	"example.com/remind/notify"
	"example.com/remind/quota"
	"example.com/remind/search"
	"example.com/remind/share"
	"example.com/remind/store"
)

// Config configures a Server. Zero values get defaults.
type Config struct {
	Version  string
	Commit   string
	Now      func() time.Time               // default time.Now
	Log      io.Writer                      // default io.Discard
	Crashes  io.Writer                      // where crash reports go; default io.Discard
	Users    []store.User                   // users to start with
	Snapshot func() (io.WriteCloser, error) // where admin snapshots go
	// WebhookSecret signs webhook deliveries.
	WebhookSecret []byte
	// RateLimits turns on per-user rate limits.
	RateLimits bool
}

// A Server is a configured remind service.
type Server struct {
	Handler    http.Handler
	Store      *store.Store
	Dispatcher *notify.Dispatcher
	Reporter   *crash.Reporter
	Log        *slog.Logger
}

// New builds a Server.
func New(cfg Config) (*Server, error) {
	if cfg.Now == nil {
		cfg.Now = time.Now
	}
	if cfg.Log == nil {
		cfg.Log = io.Discard
	}
	if cfg.Crashes == nil {
		cfg.Crashes = io.Discard
	}
	ring := crash.NewLogRing(slog.NewTextHandler(cfg.Log, nil), 12, cfg.Now)
	log := slog.New(ring)

	st := store.New(cfg.Now)
	for _, u := range cfg.Users {
		if err := st.AddUser(u); err != nil {
			return nil, fmt.Errorf("server: %w", err)
		}
	}
	d := notify.NewDispatcher(st, log, cfg.Now)

	rep := crash.NewReporter(cfg.Crashes, cfg.Now)
	rep.Version = cfg.Version
	rep.Commit = cfg.Commit
	rep.Logs = ring

	d.SetWebhookSecret(cfg.WebhookSecret)

	reg := metrics.NewRegistry()
	reg.Now = cfg.Now
	a := &api.API{
		Store:    st,
		Notify:   d,
		Lists:    share.New(cfg.Now),
		Search:   search.New(),
		Audit:    audit.New(1000, cfg.Now),
		Metrics:  reg.Handler(),
		Log:      log,
		Now:      cfg.Now,
		Snapshot: cfg.Snapshot,
	}
	if cfg.RateLimits {
		a.Limiter = quota.NewLimiter(cfg.Now)
	}
	return &Server{
		Handler:    rep.Middleware(metrics.Instrument(reg, accessLog(log, cfg.Now, a.Routes()))),
		Store:      st,
		Dispatcher: d,
		Reporter:   rep,
		Log:        log,
	}, nil
}

// Watch writes a crash report for any request in flight longer than
// limit, checking every interval until ctx ends.
func (s *Server) Watch(ctx context.Context, interval, limit time.Duration) {
	t := time.NewTicker(interval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
			s.Reporter.Check(limit)
		}
	}
}

type statusWriter struct {
	http.ResponseWriter
	status int
}

func (w *statusWriter) WriteHeader(status int) {
	w.status = status
	w.ResponseWriter.WriteHeader(status)
}

func accessLog(log *slog.Logger, now func() time.Time, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := now()
		sw := &statusWriter{ResponseWriter: w, status: http.StatusOK}
		next.ServeHTTP(sw, r)
		log.Info("request", "method", r.Method, "path", r.URL.Path, "status", sw.status,
			"dur", now().Sub(start).String(), "ua", r.UserAgent())
	})
}

// Command remind runs the reminders service.
package main

import (
	"context"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"syscall"
	"time"
	_ "time/tzdata" // zones for weekly schedules, even on minimal images

	"example.com/remind/config"
	"example.com/remind/server"
	"example.com/remind/store"
)

// Set at build time with -ldflags "-X main.version=... -X main.commit=...".
var (
	version = "(devel)"
	commit  = ""
)

func main() {
	configFile := flag.String("config", "remind.json", "configuration file; missing means defaults")
	flag.Parse()
	cfg, err := config.Load(*configFile)
	if err != nil {
		log.Fatal(err)
	}
	if err := cfg.ApplyEnv(os.Getenv); err != nil {
		log.Fatal(err)
	}
	if err := cfg.Validate(); err != nil {
		log.Fatal(err)
	}
	if err := run(cfg); err != nil {
		log.Fatal(err)
	}
}

func run(cfg config.Config) error {
	var users []store.User
	if cfg.UsersFile != "" {
		b, err := os.ReadFile(cfg.UsersFile)
		if err != nil {
			return fmt.Errorf("read users: %w", err)
		}
		var raw []struct {
			ID, Name, Email, Token, Plan string
			Admin                        bool
		}
		if err := json.Unmarshal(b, &raw); err != nil {
			return fmt.Errorf("read users: %w", err)
		}
		for _, u := range raw {
			users = append(users, store.User{ID: u.ID, Name: u.Name, Email: u.Email, Token: u.Token, Admin: u.Admin, Plan: u.Plan})
		}
	}
	crashes, err := os.OpenFile(filepath.Join(cfg.DataDir, cfg.CrashFile), os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600)
	if err != nil {
		return fmt.Errorf("open crash file: %w", err)
	}
	defer crashes.Close()

	srv, err := server.New(server.Config{
		Version: version,
		Commit:  commit,
		Log:     os.Stderr,
		Crashes: crashes,
		Users:   users,
		Snapshot: func() (io.WriteCloser, error) {
			return os.Create(filepath.Join(cfg.DataDir, cfg.SnapshotFile))
		},
		WebhookSecret: []byte(cfg.WebhookSecret),
		RateLimits:    true,
	})
	if err != nil {
		return fmt.Errorf("start: %w", err)
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	go srv.Dispatcher.Run(ctx, cfg.DispatchInterval)
	go srv.Watch(ctx, 5*time.Second, cfg.StuckAfter)

	hs := &http.Server{Addr: cfg.Addr, Handler: srv.Handler, ReadHeaderTimeout: 10 * time.Second}
	errc := make(chan error, 1)
	go func() { errc <- hs.ListenAndServe() }()
	srv.Log.Info("listening", "addr", cfg.Addr, "version", version)

	select {
	case err := <-errc:
		return fmt.Errorf("serve: %w", err)
	case <-ctx.Done():
	}
	shutdown, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	srv.Dispatcher.Stop()
	if err := hs.Shutdown(shutdown); err != nil && !errors.Is(err, http.ErrServerClosed) {
		return fmt.Errorf("shutdown: %w", err)
	}
	return nil
}

